import json
bl=np.load('base_logits.npy'); ids=json.load(open('all_ids.json'))
def sm(z): z=z-z.max(1,keepdims=True); e=np.exp(z); return e/e.sum(1,keepdims=True)
def f1macro(g,p):
    f=[]
    for c in range(4):
        tp=((p==c)&(g==c)).sum(); fp=((p==c)&(g!=c)).sum(); fn=((p!=c)&(g==c)).sum()
        f.append(2*tp/max(2*tp+fp+fn,1))
    return np.mean(f)
def load_pass(p):
    m=json.load(open(p+'/meta.json')); lg=np.load(p+'/logits.npy'); mid=m['ids']
    return lg[[mid.index(i) for i in ids]] if mid!=ids else lg
models={'m1536v1':np.load('lg_pass25.npy'),'m1536v3':np.load('lg_pass29.npy'),'m2048old':load_pass('pass_12'),'m1536old':load_pass('pass_10'),'m1024zero':load_pass('pass_11')}
rng=np.random.default_rng(1); R=4000; N=400
for k in [1.0,1.25,1.5,2.0]:
    P=sm(bl/k); cum=P.cumsum(1)
    res={}
    idxs=rng.integers(0,1000,(R,N)); u=rng.random((R,N))
    golds=(u[...,None]>cum[idxs]).sum(-1)
    bp=bl.argmax(1)
    for name,lg in models.items():
        d=lg-bl; ep=(bl/k+d).argmax(1)
        fails=0; accfail=0; f1fail=0; flips=[]
        for r in range(R):
            ii=idxs[r]; g=golds[r]; b=bp[ii]; e=ep[ii]
            da=(e==g).sum()-(b==g).sum(); flips.append((e!=b).sum())
            fa=da<-4; ff=f1macro(g,e)<f1macro(g,b)-0.02
            accfail+=fa; f1fail+=ff; fails+=(fa or ff)
        res[name]=(np.mean(flips).round(1), accfail/R, f1fail/R, fails/R)
    print('k',k,'base acc %.3f'%P.max(1).mean())
    for n,v in res.items(): print('   %-10s flips %.1f  P(accfail) %.3f P(f1fail) %.3f P(fail) %.3f'%((n,)+v))
